import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Extract text content with fallback chain
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline') || items[0];
  const textContent = textItem?.text ?? 'Collection';

  // Parse typography from config or use defaults
  const fontSize = textItem?.typography?.fontSize ?? 96;

  // Resolve colors from spec
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Create root group
  const group = new THREE.Group();
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Track resources for cleanup
  const resources = {
    textures: [],
    timelines: [],
    primitives: []
  };

  // Create backdrop plane (engineered gradient surface)
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);

  // Build TSL shader for vertical gradient (surface to ink)
  const uvNode = uv();
  const gradientFactor = uvNode.y; // 0 bottom -> 1 top

  // Gradient from surface (#0b0b10) at bottom to ink (#16161d) at top
  // surface = rgb(11, 11, 16), ink = rgb(22, 22, 29)
  const colorBottom = vec3(11.0 / 255.0, 11.0 / 255.0, 16.0 / 255.0);
  const colorTop = vec3(22.0 / 255.0, 22.0 / 255.0, 29.0 / 255.0);
  const gradientColor = mix(colorBottom, colorTop, gradientFactor);

  const backdropMaterial = new MeshBasicNodeMaterial({
    colorNode: gradientColor,
    fog: false,
    side: THREE.DoubleSide
  });

  const backdropMesh = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdropMesh.position.z = -2.5;
  backdropMesh.castShadow = false;
  backdropMesh.receiveShadow = false;
  group.add(backdropMesh);

  // Create text element with serif display font (Lora)
  // FontSize converted to scene units: 96px display ≈ 0.62 scene units at standard scale
  const sceneUnitFontSize = (fontSize / 96) * 0.62;

  const textMesh = ctx.fontAtlas.createText(textContent, {
    fontSize: sceneUnitFontSize,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0
  });

  // Position text in upper-center region of frame
  textMesh.position.set(0, 1.2, 0);
  group.add(textMesh);

  // Load and apply card image as a small accent plane below text
  // Atlas region: 0, 0, 512, 320 (feature-card.png)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then(texture => {
      texture.colorSpace = THREE.SRGBColorSpace;
      resources.textures.push(texture);

      // Aspect ratio: 512/320 = 1.6
      const cardWidth = 2.0;
      const cardHeight = cardWidth / 1.6;

      const cardGeometry = new THREE.PlaneGeometry(cardWidth, cardHeight);

      // Use TSL node material to apply texture
      const cardTexture = texture;
      const cardMaterial = new MeshBasicNodeMaterial({
        map: cardTexture,
        colorSpace: THREE.SRGBColorSpace,
        side: THREE.DoubleSide,
        fog: false
      });

      const cardMesh = new THREE.Mesh(cardGeometry, cardMaterial);
      cardMesh.position.set(0, -0.8, 0.05); // Slight z-offset to appear in front
      group.add(cardMesh);
    }).catch(err => {
      console.warn('Failed to load card image:', err);
    });
  }

  // Cleanup function
  group.userData.cleanup = () => {
    // Dispose materials
    backdropMaterial.dispose();
    backdropGeometry.dispose();

    // Dispose textures
    resources.textures.forEach(tex => tex.dispose());

    // Kill timelines
    resources.timelines.forEach(tl => tl.kill());

    // Cleanup primitives
    resources.primitives.forEach(p => {
      if (p.cleanup) p.cleanup();
    });
  };

  group.userData.handlers = {};

  return group;
}
